-- step43: блок «Мастер» (lb-master) — 6 пунктов вместо 5 (тексты пользователя; EN — перевод). Повторный запуск ничего не меняет.
--   Новый TV text-6-bl2-study (копия настроек text-5-bl2-study, те же шаблоны 1, 8, 15); значения text-1..6-bl2-study главных RO 1 / RU 193 / EN 1001.
--   Страницы с собственными пунктами (ресницы 626 / 1626, лазер 627 / 628 / 1627) — не трогаются.
SET NAMES utf8mb4;
  SELECT source, property_preprocess, type, 'text-6-bl2-study', 'Текст 6', description, editor_type, category, locked, elements, `rank` + 1, display, default_text, properties, input_properties, output_properties, static, static_file
  FROM Impulse_Digital_X_site_tmplvars WHERE name = 'text-5-bl2-study';
  SELECT (SELECT id FROM Impulse_Digital_X_site_tmplvars WHERE name = 'text-6-bl2-study'), templateid, `rank` FROM Impulse_Digital_X_site_tmplvar_templates
  WHERE tmplvarid = (SELECT id FROM Impulse_Digital_X_site_tmplvars WHERE name = 'text-5-bl2-study');
DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE contentid = 1 AND tmplvarid IN (SELECT id FROM Impulse_Digital_X_site_tmplvars WHERE name IN ('text-1-bl2-study','text-2-bl2-study','text-3-bl2-study','text-4-bl2-study','text-5-bl2-study','text-6-bl2-study'));
DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE contentid = 193 AND tmplvarid IN (SELECT id FROM Impulse_Digital_X_site_tmplvars WHERE name IN ('text-1-bl2-study','text-2-bl2-study','text-3-bl2-study','text-4-bl2-study','text-5-bl2-study','text-6-bl2-study'));
DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE contentid = 1001 AND tmplvarid IN (SELECT id FROM Impulse_Digital_X_site_tmplvars WHERE name IN ('text-1-bl2-study','text-2-bl2-study','text-3-bl2-study','text-4-bl2-study','text-5-bl2-study','text-6-bl2-study'));
